    cy.get('[data-testid="card-type-indicator"]').should('contain', 'Visa');

    cy.get('[data-testid="expiry-input"]').type(testUser.expiryDate);
    cy.get('[data-testid="cvv-input"]').type(testUser.cvv);

    // Step 7: Calculate shipping (async calculation)
    cy.get('[data-testid="shipping-method-select"]').select('standard');
    cy.get('[data-testid="shipping-calculation-spinner"]').should('be.visible');
    cy.get('[data-testid="shipping-calculation-spinner"]').should('not.exist', { timeout: 5000 });
    cy.get('[data-testid="shipping-cost"]').should('contain', '$9.99');

    // Step 8: Calculate taxes (async calculation)
    cy.get('[data-testid="tax-calculation-spinner"]').should('be.visible');
    cy.get('[data-testid="tax-calculation-spinner"]').should('not.exist', { timeout: 5000 });
    cy.get('[data-testid="tax-amount"]').should('not.be.empty');

    // Step 9: Verify order summary
    cy.get('[data-testid="order-summary"]').should('be.visible');
    cy.get('[data-testid="subtotal"]').should('contain', '$');
    cy.get('[data-testid="total-amount"]').should('contain', '$');

    // Step 10: Submit order (async processing)
    cy.get('[data-testid="place-order-btn"]').click();
    cy.get('[data-testid="order-processing-spinner"]').should('be.visible');
    cy.get('[data-testid="order-processing-spinner"]').should('not.exist', { timeout: 10000 });

    // Step 11: Verify order confirmation
    cy.url().should('include', '/order-confirmation');
    cy.get('[data-testid="confirmation-message"]').should('contain', 'Order placed successfully');
    cy.get('[data-testid="order-number"]').should('match', /^ORD-\d{10}$/);
    cy.get('[data-testid="confirmation-email"]').should('contain', testUser.email);
  });

